import {normalizePictureFrame,pictureFrameMatches} from './tools/board-resource-p7.mjs';import {PUZZLE_ILLUSTRATIONS} from './public/house-puzzle-content.js';import {createHash} from 'node:crypto';
const id=n=>'00000000-0000-4000-8000-'+n.toString(16).padStart(12,'0'),art=PUZZLE_ILLUSTRATIONS[0],hash=x=>createHash('sha256').update(x).digest('hex');
const scope={houseIndex:0,houseId:id(1),selfId:id(2),serverEpoch:id(3),memberIds:[id(2),id(4),id(5),id(6),id(7),id(8)],generation:1,accessGeneration:1};
const snapshot={serverEpoch:id(3),generation:1,accessGeneration:1,controller:true,durable:{house:{id:id(1)},selfId:id(2),zoneId:'lounge',puzzle:{revision:1,current:{id:id(9),ruleset:1,illustrationId:art.id,illustrationVersion:art.version,illustrationDigest:art.digest,completed:false,placements:[]}}},puzzleRoster:{serverEpoch:id(3),houseId:id(1),roundId:id(9),revision:1,memberIds:[],selfParticipationId:null}};
const expected={houseIndex:0,puzzleRevision:1,roundHash:hash(id(9)),illustrationId:art.id,illustrationVersion:art.version,illustrationDigest:art.digest,completed:false,placements:[],rosterRevision:1,rosterMembers:[],selfHashes:Array(6).fill(null)};
const records=[];for(const change of ['valid','generation','accessGeneration','observer','ruleset','foreignHouse']){const bad=structuredClone(snapshot);if(change==='generation')bad.generation=99;if(change==='accessGeneration')bad.accessGeneration=99;if(change==='observer')bad.controller=false;if(change==='ruleset')bad.durable.puzzle.current.ruleset=99;if(change==='foreignHouse')bad.durable.house.id=id(99);const frame=normalizePictureFrame(bad,scope);records.push({change,scopeValid:frame.scopeValid,accepted:pictureFrameMatches(frame,expected)});}console.log(JSON.stringify(records));
